package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal = decimal.NewFromInt(0)    // PIC 9(11)V99 len=13 = 0
var WsCount int64 = 0                                  // PIC 9(5) len=5 = 0
var WsPrinEd string // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string  // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec

var loanFile *os.File
var scanner *bufio.Scanner

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

// parse digits only field
func parseDigitsField(s string) int64 {
	var v int64
	found := false
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			v = v*10 + int64(ch-'0')
			found = true
		}
	}
	if !found {
		return 0
	}
	return v
}

func storeDecimal(val decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// val is already rounded/truncated to scale
	// apply overflow: keep low-order digits (mod 10^(intDigits+scale))
	totalDigits := int32(intDigits) + scale
	modulus := decimal.New(1, totalDigits) // 10^totalDigits
	// integer representation: val * 10^scale
	intVal := val.Shift(scale)
	// modulo - keep sign handling simple (values are non-negative)
	// for negative, make positive mod then restore sign?
	if intVal.IsNegative() {
		// COBOL unsigned fields: behaviour undefined, but mimic wrap
		neg := intVal.Neg()
		rem := neg.Mod(modulus)
		intVal = rem.Neg()
	} else {
		intVal = intVal.Mod(modulus)
	}
	return intVal.Shift(-scale)
}

func formatPIC9_5(n int64, digits int) string {
	// keep low-order digits
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	n = n % mod
	if n < 0 {
		n += mod
	}
	s := fmt.Sprintf("%0*d", digits, n)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

func formatEdited(val decimal.Decimal, picture string) string {
	// picture like "Z,ZZZ,ZZ9.99"
	// split at '.'
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	// count integer digit positions
	intDigitPos := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			intDigitPos++
		}
	}
	scale := len(fracPic) // for our cases 2, all '9'
	// ensure val scale
	// val may be negative; work with absolute? editing will handle sign? Assume positive.
	isNeg := val.IsNegative()
	if isNeg {
		val = val.Neg()
	}
	// overflow: keep low-order integer digits
	// compute integer part modulo 10^intDigitPos
	// get integer part
	// we can compute intPart = floor(val)
	intPartDec := val.Truncate(0)
	// overflow modulo
	modInt := decimal.New(1, int32(intDigitPos))
	intPartDec = intPartDec.Mod(modInt)
	intPart := intPartDec.IntPart() // fits in int64 for our ranges (max 11 digits)
	// fractional part: (val - floor(original truncated? ) but after overflow integer part changed,
	// fractional stays same as original's fraction)
	// fractional = (val - floor(val_original)) scaled
	// Use original val for fraction (overflow doesn't affect fraction)
	// Get fraction from original val: val - trunc(val)
	// But we replaced intPartDec with modulo; need fraction from original val
	fracDec := val.Sub(val.Truncate(0))
	// scale fraction to integer 0..10^scale-1
	fracInt := int64(0)
	if scale > 0 {
		fracScaled := fracDec.Shift(int32(scale))
		// round/truncate? val already at that scale, so exact
		fracScaled = fracScaled.Truncate(0)
		fracInt = fracScaled.IntPart()
		if fracInt < 0 {
			fracInt = -fracInt
		}
		// overflow fraction within scale already
	}

	// build integer digits string zero padded
	intDigitsStr := fmt.Sprintf("%0*d", intDigitPos, intPart)
	// Build int formatted array
	intPatRunes := []rune(intPic)
	outInt := make([]rune, len(intPatRunes))
	dIdx := 0
	for i, r := range intPatRunes {
		if r == 'Z' || r == '9' {
			outInt[i] = rune(intDigitsStr[dIdx])
			dIdx++
		} else {
			outInt[i] = r // ','
		}
	}
	// Z suppression
	suppressed := true
	for i, patCh := range intPatRunes {
		if patCh == 'Z' || patCh == '9' {
			digit := outInt[i]
			if suppressed {
				if patCh == 'Z' && digit == '0' {
					outInt[i] = ' '
					// remain suppressed
				} else {
					// patCh == '9' -> show even if zero, stops suppression
					// patCh == 'Z' with non-zero -> show
					suppressed = false
					// digit stays as is ('0' for 9 case or non-zero)
				}
			} else {
				// already not suppressed, keep digit
			}
		} else if patCh == ',' {
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		}
	}

	// build final
	var sb strings.Builder
	for _, r := range outInt {
		sb.WriteRune(r)
	}
	if dotIdx >= 0 {
		sb.WriteRune('.')
		fracStr := fmt.Sprintf("%0*d", scale, fracInt)
		sb.WriteString(fracStr)
	}
	result := sb.String()
	// sign handling (not needed for this program, but keep)
	if isNeg {
		// COBOL would show sign? For unsigned edited, ignore.
		// Prepend minus if room? Simplistic: replace leading space with '-'
		// Not required for tests.
	}
	// ensure length equals picture length
	// picture length is len(picture) (with '.' and commas)
	if len(result) < len(picture) {
		result = strings.Repeat(" ", len(picture)-len(result)) + result
	}
	return result
}

// paragraph functions

func MainPara() {
	OpenLoanFile()
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	CloseLoanFile()
	SummaryPara()
}

func OpenLoanFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file does not exist, treat as empty
		if os.IsNotExist(err) {
			WsEofFlag = "Y"
			loanFile = nil
			scanner = nil
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	loanFile = f
	scanner = bufio.NewScanner(f)
	// allow long lines
	// default 64k is enough (21 bytes)
}

func CloseLoanFile() {
	if loanFile != nil {
		loanFile.Close()
	}
}

func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if !scanner.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := scanner.Text()
	// LINE SEQUENTIAL: pad with spaces to 21 if shorter
	if len(line) < 21 {
		line = padRight(line, 21)
	} else if len(line) > 21 {
		line = line[:21]
	}
	// parse fields 0-based
	lrAcct := line[0:6]
	lrPrinStr := line[6:15]  // 9
	lrRateStr := line[15:19] // 4
	lrYearsStr := line[19:21] // 2

	nPrin := parseDigitsField(lrPrinStr)
	nRate := parseDigitsField(lrRateStr)
	nYears := parseDigitsField(lrYearsStr)

	loanRec.LrAcct = lrAcct
	loanRec.LrPrincipal = decimal.New(nPrin, -2)
	loanRec.LrRate = decimal.New(nRate, -2)
	loanRec.LrYears = nYears
}

func ProcessPara() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	raw := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears)).Shift(-2)
	rounded := raw.Round(2)
	WsInterest = storeDecimal(rounded, 9, 2)

	// ADD WS-INTEREST TO WS-TOTAL
	sum := WsTotal.Add(WsInterest)
	// truncate to scale 2 (already)
	sum = sum.Truncate(2)
	WsTotal = storeDecimal(sum, 11, 2)

	// ADD 1 TO WS-COUNT
	WsCount = WsCount + 1
	// overflow 9(5)
	mod := int64(100000)
	WsCount = WsCount % mod
	if WsCount < 0 {
		WsCount += mod
	}

	// MOVE LR-PRINCIPAL TO WS-PRIN-ED
	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	// MOVE WS-INTEREST TO WS-INT-ED
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")

	// DISPLAY LR-ACCT " " WS-PRIN-ED " " WS-INT-ED
	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)

	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	// DISPLAY "RECORDS: " WS-COUNT
	fmt.Printf("RECORDS: %s\n", formatPIC9_5(WsCount, 5))
	// DISPLAY "TOTAL INTEREST: " WS-TOTAL-ED
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func main() {
	WsEofFlag = "N"
	WsInterest = decimal.NewFromInt(0)
	WsTotal = decimal.NewFromInt(0)
	WsCount = 0
	MainPara()
}
